INSERT INTO `planificaciones_anuales` (`id`, `docente_id`, `espacio_id`, `anio_lectivo`, `division`, `diagnostico`, `fundamentacion`, `metas`, `objetivos`, `contenidos`, `capacidades`, `transversales`, `unidades`, `estrategias`, `formatos_pedagogicos`, `recursos`, `articulacion`, `evaluacion_criterios`, `evaluacion_instrumentos`, `evaluacion_momentos`, `bibliografia`, `estado`, `devolucion_directivo`, `revisado_por`, `fecha_revision`) VALUES
(1, 4, 41, 2026, 'A', 'Curso de 4.º A con 26 estudiantes. La mitad vive en zona de quintas y conoce tareas de huerta. Se observan buenas habilidades prácticas y dificultades para registrar datos y explicar por escrito lo que se hace.', 'El espacio introduce la mirada sistémica sobre la producción vegetal. La huerta escolar y las quintas de Colonia Caroya permiten comparar planteos convencionales y agroecológicos con datos propios.', '[]', '["Identificar los problemas ecológicos que plantea la agricultura convencional.","Comprender las semejanzas y diferencias entre los ecosistemas naturales y los agroecosistemas.","Dimensionar el impacto ambiental que producen las diferentes prácticas productivas e industriales en diversos agroecosistemas.","Valorar la contribución de la Agroecología como disciplina científica para diseñar, manejar y evaluar sistemas de producción vegetal, animal y agroindustrial."]', '[{"texto":"Aproximación a los conceptos de sistemas, agroecosistemas, agroambientes y sustentabilidad.","meta":null,"indicadores":[],"fuente":"diseno_2011_2015","contenido_id":1592,"prioridad":"esencial"},{"texto":"Problematización derivada de agroambientes convencionales, alternativos y de planteos agroecológicos.","meta":null,"indicadores":[],"fuente":"diseno_2011_2015","contenido_id":1593,"prioridad":"esencial"},{"texto":"Reconocimiento del valor de la sustentabilidad de los sistemas agroambientales en el mediano y largo plazo.","meta":null,"indicadores":[],"fuente":"diseno_2011_2015","contenido_id":1594,"prioridad":"esencial"},{"texto":"Comprensión de fundamentos, alcances y limitaciones de prácticas de producción alternativa, orgánicas o ecológicas.","meta":null,"indicadores":[],"fuente":"diseno_2011_2015","contenido_id":1595,"prioridad":"esencial"},{"texto":"Análisis del funcionamiento de máquinas y equipos típicos de la producción vegetal, así como de las normas de seguridad e higiene en el trabajo y de protección del medio ambiente.","meta":null,"indicadores":[],"fuente":"diseno_2011_2015","contenido_id":1598,"prioridad":"complementario"},{"texto":"Implementación y análisis de modelos que incluyan buenas prácticas en sistemas de producción vegetal de importancia regional.","meta":null,"indicadores":[],"fuente":"diseno_2011_2015","contenido_id":1599,"prioridad":"esencial"}]', '["Abordaje y resolución de situaciones problemáticas","Pensamiento crítico","Trabajo colaborativo y cooperativo"]', '[{"tema":"Educación Ambiental Integral","como":"Eje del espacio: uso del suelo y del agua, compostaje y biodiversidad funcional."},{"tema":"Educación Económica y Financiera","como":"Registro de costos e insumos de la huerta."}]', '[{"titulo":"Del ecosistema al agroecosistema","periodo":"Marzo - mayo","horas":66,"contenidos":"Sistemas, agroecosistemas y sustentabilidad. Problematización de planteos convencionales y alternativos.","actividades":"Recorrida por la huerta y una quinta vecina, croquis del sistema y cuadro comparativo."},{"titulo":"Suelo vivo y manejo alternativo","periodo":"Junio - agosto","horas":54,"contenidos":"Prácticas de producción alternativa, orgánicas o ecológicas.","actividades":"Compostera, ensayo de abonos y registro semanal."},{"titulo":"Equipos, seguridad y buenas prácticas","periodo":"Septiembre - diciembre","horas":72,"contenidos":"Máquinas y equipos de la producción vegetal. Buenas prácticas.","actividades":"Protocolo de seguridad de la huerta y evaluación de sustentabilidad del sistema."}]', 'Estudio de casos locales, experimentación en huerta, trabajo en equipos con roles rotativos y puesta en común escrita.', '["Taller","Trabajo de campo","Proyecto"]', 'Huerta y compostera, termómetro de compost, tiras de pH, lupas, planillas de registro, Tomo 11 del Diseño Curricular.', 'Biología de 4.º año: relación entre ambiente y salud. Matemática: lectura de los registros de temperatura en tablas y gráficos.', 'Explica el agroecosistema como sistema. Registra datos completos y los interpreta. Fundamenta alternativas de manejo. Cumple las normas de seguridad. Los criterios se comparten y conversan con el curso en marzo.', 'Rúbrica de trabajo de campo, portfolio de registros, informe por equipo y coloquio final.', 'Inicial: mapa de ideas previas. Formativa: devoluciones quincenales del portfolio y autoevaluación por unidad. Final: informe de sustentabilidad y coevaluación.', 'Ministerio de Educación de Córdoba. Diseño Curricular de la Educación Secundaria, Tomo 11: Agro y Ambiente (2012-2015).', 'aprobada', 'Muy buena integración entre registro de datos y trabajo de campo. Se aprueba.', 2, '2026-03-27 10:30:00');
INSERT INTO `planificaciones_anuales` (`id`, `docente_id`, `espacio_id`, `anio_lectivo`, `division`, `diagnostico`, `fundamentacion`, `metas`, `objetivos`, `contenidos`, `capacidades`, `transversales`, `unidades`, `estrategias`, `formatos_pedagogicos`, `recursos`, `articulacion`, `evaluacion_criterios`, `evaluacion_instrumentos`, `evaluacion_momentos`, `bibliografia`, `estado`, `devolucion_directivo`, `revisado_por`, `fecha_revision`) VALUES
(2, 7, 33, 2026, 'A', 'El curso resuelve problemas de proporcionalidad directa. Cuesta pasar de la tabla a la fórmula y leer la pendiente de una recta en contexto.', 'Las funciones permiten modelizar situaciones reales. Se parte de datos medidos por el propio curso para dar sentido a la pendiente y la ordenada al origen.', '["Modelizar situaciones vinculadas a la función lineal, cuadrática, racional, exponencial, logarítmica y trigonométricas.","Comunicar información estadística a través de tablas de contingencia y distribuciones de probabilidad."]', '["Modelizar situaciones con funciones lineales y cuadráticas.","Interpretar parámetros en el contexto de cada problema.","Comunicar procedimientos con distintos registros."]', '[{"texto":"Análisis de funciones lineales f(x) = kx + b, presentadas en textos, tablas, gráficos y fórmulas, en situaciones extra e intramatemáticas.","meta":"Modelizar situaciones vinculadas a la función lineal, cuadrática, racional, exponencial, logarítmica y trigonométricas.","indicadores":["Reconoce y explica funciones lineales en base a la interpretación de textos, tablas, gráficos y fórmulas.","Interpreta y comunica dominio e imagen en situaciones que se modelizan con funciones lineales.","Reconoce gráficamente y comunica puntos de intersección con los ejes coordenados, intervalos de positividad y negatividad, apelando al uso del software cuando sea posible.","Relaciona la variación de x en función de y en la ecuación y = kx + b al escribir la inversa de una función lineal dada.","Interpreta y explica las características del gráfico de la inversa de una función lineal dada.","Lee una situación, selecciona la información relevante y usa la función lineal para modelizarla.","Busca y selecciona información en distintas fuentes sobre situaciones reales (incluidas las de interés simple) que se modelizan con funciones lineales."],"fuente":"pda_2025","contenido_id":1309,"prioridad":"esencial"},{"texto":"Análisis de funciones cuadráticas f(x) = ax2 + bx + c , presentadas en textos, tablas, gráficos y fórmulas.","meta":"Modelizar situaciones vinculadas a la función lineal, cuadrática, racional, exponencial, logarítmica y trigonométricas.","indicadores":["Reconoce y explica variaciones cuadráticas, en base a la interpretación de textos, tablas, gráficos y fórmulas.","Interpreta y comunica características del gráfico (orientación de las ramas de la parábola, desplazamiento horizontal y vertical, vértice y puntos de intersección con los ejes coordenados ) de las variaciones cuadráticas y = ax2 + bx + c, a partir de sus parámetros, apelando al uso del software cuando sea posible.","Compara y explica procedimientos (incluida la fórmula de Bhaskara) para resolver ecuaciones cuadráticas ax2 + bx + c = 0.","Comunica —a partir de la lectura del gráfico— dominio; imagen; máximo; mínimo; puntos de intersección con los ejes coordenados; intervalos de positividad, negatividad, crecimiento y decrecimiento; en situaciones que se modelizan con funciones cuadráticas."],"fuente":"pda_2025","contenido_id":1310,"prioridad":"esencial"},{"texto":"Análisis de las medidas estadísticas de tendencia central, de variables cuantitativas discretas y continuas.","meta":"Comunicar información estadística a través de tablas de contingencia y distribuciones de probabilidad.","indicadores":["Lee una situación y diferencia variables cuantitativas discretas de las continuas que contiene un conjunto de datos.","Justifica la elección del gráfico estadístico más apropiado (histogramas para más de 50 datos, de puntos) para comunicar la información de las tablas frecuencias de variables cuantitativas.","Describe la distribución de variables cuantitativas atendiendo a la dispersión y forma de los gráficos estadísticos (histogramas, de puntos), apelando al uso del software cuando sea posible.","Interpreta y comunica medidas de tendencia central (moda, mediana y media aritmética) de variables cuantitativas, atendiendo a la dispersión de los datos observada en los gráficos (sin el cálculo de medidas de dispersión)."],"fuente":"pda_2025","contenido_id":1313,"prioridad":"esencial"},{"texto":"Cuantificación de la probabilidad condicional de eventos.","meta":"Comunicar información estadística a través de tablas de contingencia y distribuciones de probabilidad.","indicadores":["Lee una situación y reconoce eventos excluyentes (disjuntos), no excluyentes, independientes y dependientes en el contexto de experimentos aleatorios.","Explica diferencias entre eventos excluyentes (disjuntos) y eventos independientes.","Interpreta y comunica la probabilidad de que ocurra un evento habiendo ocurrido otro (eventos dependientes) en el contexto del experimento aleatorio.","Reconoce y justifica la necesidad de recurrir al uso de fórmulas de adición para el cálculo de la probabilidad condicional."],"fuente":"pda_2025","contenido_id":1312,"prioridad":"complementario"}]', '["Abordaje y resolución de situaciones problemáticas","Oralidad, lectura y escritura","Gestión y monitoreo del propio aprendizaje"]', '[{"tema":"Cultura Digital y Ciencias de la Computación","como":"Uso de planilla de cálculo y GeoGebra para representar datos."}]', '[{"titulo":"Función lineal en contexto","periodo":"Marzo - junio","horas":52,"contenidos":"Funciones lineales en textos, tablas, gráficos y fórmulas.","actividades":"Modelización de datos de frecuencia cardíaca y de riego."},{"titulo":"Función cuadrática","periodo":"Julio - septiembre","horas":40,"contenidos":"Funciones cuadráticas y sus parámetros.","actividades":"Problemas de área máxima de canteros y trayectorias."},{"titulo":"Estadística y probabilidad","periodo":"Octubre - diciembre","horas":40,"contenidos":"Tendencia central y probabilidad condicional.","actividades":"Análisis de datos propios y presentación oral."}]', 'Resolución de problemas, debate de procedimientos, trabajo con software y devolución entre pares.', '["Materia/Asignatura","Laboratorio"]', 'Planilla de cálculo, GeoGebra, cronómetros, datos registrados por el curso.', 'Participa del proyecto "El cuerpo humano y la actividad física" con Educación Física y Biología.', 'Selecciona un modelo adecuado, interpreta sus parámetros, justifica procedimientos y comunica resultados.', 'Resolución individual de problemas, informe de modelización y lista de cotejo de exposición.', 'Inicial: problema diagnóstico. Formativa: revisión de borradores y autoevaluación. Final: informe de modelización.', 'Currículum Córdoba. Progresiones de Aprendizaje: Matemática (versión en consulta 2025).', 'pendiente_revision', NULL, NULL, NULL);
INSERT INTO `planificaciones_anuales` (`id`, `docente_id`, `espacio_id`, `anio_lectivo`, `division`, `diagnostico`, `fundamentacion`, `metas`, `objetivos`, `contenidos`, `capacidades`, `transversales`, `unidades`, `estrategias`, `formatos_pedagogicos`, `recursos`, `articulacion`, `evaluacion_criterios`, `evaluacion_instrumentos`, `evaluacion_momentos`, `bibliografia`, `estado`, `devolucion_directivo`, `revisado_por`, `fecha_revision`) VALUES
(3, 5, 58, 2026, 'A', 'El grupo maneja la tabla periódica. Presenta dificultades en el cálculo de concentraciones y en el uso seguro del laboratorio.', 'Se trabaja la química del agua y del suelo de la zona, con mediciones simples y lectura crítica de resultados.', '["Debatir y reflexionar sobre las intervenciones y contribuciones de la química ante los desafíos científicos y ambientales actuales, especialmente sobre el desarrollo de nuevos materiales y procesos industriales.","Indagar sobre diversas reacciones químicas, sus reactivos y productos, así como las condiciones en las que ocurren, reconociendo que pueden cuantificarse y explicarse mediante modelos científicos.","Reconocer los compuestos del carbono y sus propiedades, comprendiendo su importancia en los seres vivos y los usos cotidianos, para argumentar, validar información y tomar decisiones sobre el cuidado de la salud y el ambiente."]', '["Calcular e interpretar concentraciones de soluciones.","Reconocer reacciones ácido-base en el ambiente."]', '[{"texto":"Interpretación del concepto de concentración de una solución a través de cálculos, utilizando diferentes unidades (% m/m, % m/v, % v/v, molaridad) y sus correlaciones, y reconociendo la importancia que tienen al tomar decisiones seguras en situaciones de la vida cotidiana.","meta":"Debatir y reflexionar sobre las intervenciones y contribuciones de la química ante los desafíos científicos y ambientales actuales, especialmente sobre el desarrollo de nuevos materiales y procesos industriales.","indicadores":["Identifica y utiliza correctamente el material de laboratorio en la preparación de soluciones de diferentes concentraciones, considerando las recomendaciones de bioseguridad y las de manipulación de reactivos, a partir de la indagación de las fichas de seguridad.","Realiza cálculos de concentraciones de soluciones expresadas en % m/m, % m/v, %v/v y molaridad, a partir de datos experimentales, para resolver situaciones problemáticas.","Interpreta etiquetas de productos comerciales, identificando la concentración de sus componentes.","Selecciona información y argumenta sobre la importancia de conocer la concentración de soluciones y su utilización en distintos ámbitos (cotidiano, científico y tecnológico)."],"fuente":"pda_2025","contenido_id":2088,"prioridad":"esencial"},{"texto":"Reconocimiento de algunas reacciones ácido-base y de neutralización, a nivel macroscópico, submicroscópico y simbólico, presentes en el ambiente y en los seres vivos.","meta":"Indagar sobre diversas reacciones químicas, sus reactivos y productos, así como las condiciones en las que ocurren, reconociendo que pueden cuantificarse y explicarse mediante modelos científicos.","indicadores":["Clasifica sustancias ácidas, básicas y neutras a través de métodos cuali y cuantitativos, mediante el uso de indicadores ácido-base e instrumentos de medición de pH.","Relaciona las evidencias macroscópicas de una reacción ácido-base (por ejemplo, el cambio de color de indicadores o la liberación de gas) con su representación simbólica, a través de ecuaciones químicas.","Experimenta con reacciones de neutralización, realiza inferencias, y justifica la formación de productos mediante cálculos estequiométricos y de pH.","Reflexiona sobre la importancia de conocer y aplicar las normas de bioseguridad en la manipulación de ácidos y bases, reconociendo cómo este conocimiento orienta su actuación responsable en el laboratorio."],"fuente":"pda_2025","contenido_id":2099,"prioridad":"esencial"},{"texto":"Cuantificación del cambio químico a partir de la consideración del principio de conservación de la masa y la realización de cálculos estequiométricos sencillos, estableciendo las relaciones mol-mol, masamasa, masa-volumen, mol-masa.","meta":"Indagar sobre diversas reacciones químicas, sus reactivos y productos, así como las condiciones en las que ocurren, reconociendo que pueden cuantificarse y explicarse mediante modelos científicos.","indicadores":["Interpreta el significado de los coeficientes estequiométricos, y establece las diferencias con el índice de atomicidad en la formulación de compuestos químicos.","Balancea ecuaciones químicas para corroborar la conservación de la masa.","Utiliza el principio de conservación de la masa para predecir la cantidad de productos obtenidos, calcular el rendimiento e identificar el reactivo limitante y en exceso.","Resuelve situaciones problemáticas que involucran cálculos estequiométricos sencillos, basados en relaciones mol-mol, masa-masa, masa-mol, masa-volumen y volumen-mol, utilizando la ecuación química balanceada como referencia."],"fuente":"pda_2025","contenido_id":2098,"prioridad":"esencial"},{"texto":"Reconocimiento de los principales grupos funcionales y su relación con las propiedades de las biomoléculas, y de algunos materiales y sustancias de uso cotidiano (hidrocarburos, polímeros naturales y sintéticos, alcoholes, siliconas, entre otros).","meta":"Reconocer los compuestos del carbono y sus propiedades, comprendiendo su importancia en los seres vivos y los usos cotidianos, para argumentar, validar información y tomar decisiones sobre el cuidado de la salud y el ambiente.","indicadores":["Identifica los principales grupos funcionales presentes en la estructura química de las biomoléculas y sustancias de uso cotidiano.","Realiza inferencias y construye explicaciones sobre las propiedades físicas de compuestos orgánicos (por ejemplo, biomoléculas, hidrocarburos, polímeros, alcoholes, siliconas, entre otros), a partir de la experimentación, el análisis de datos y la selección de información en diversas fuentes.","Relaciona las propiedades de los hidrocarburos, polímeros, alcoholes y siliconas con los grupos funcionales presentes en su estructura (por ejemplo, solubilidad en agua y solventes orgánicos, propiedades ácido base y polaridad).","Analiza los efectos que producen algunos materiales y sustancias de uso cotidiano en el ambiente, y reflexiona en torno a los cambios culturales en favor del desarrollo sostenible."],"fuente":"pda_2025","contenido_id":2091,"prioridad":"complementario"}]', '["Abordaje y resolución de situaciones problemáticas","Pensamiento crítico"]', '[{"tema":"Educación Ambiental Integral","como":"Calidad del agua de riego."}]', '[{"titulo":"Soluciones y concentración","periodo":"Marzo - julio","horas":80,"contenidos":"Concentración y estequiometría.","actividades":"Preparación de soluciones en laboratorio."},{"titulo":"Ácidos y bases en el ambiente","periodo":"Agosto - diciembre","horas":85,"contenidos":"Reacciones ácido-base y polímeros.","actividades":"Medición de pH de suelo y agua de riego."}]', 'Experimentación guiada y análisis de casos.', '["Laboratorio"]', 'Laboratorio escolar, tiras de pH, material volumétrico.', 'Sistemas Agroambientales III: calidad del agua en procesos agroindustriales.', 'Calcula concentraciones y explica resultados.', 'Informe de laboratorio.', 'Inicial, en proceso y final.', 'Currículum Córdoba. Progresiones de Aprendizaje: Ciencias Naturales (versión en consulta 2025).', 'requiere_ajustes', 'Ampliar los criterios de evaluación y sumar instancias de autoevaluación. Detallar las normas de seguridad del laboratorio.', 2, '2026-04-10 09:00:00');
INSERT INTO `planificaciones_anuales` (`id`, `docente_id`, `espacio_id`, `anio_lectivo`, `division`, `diagnostico`, `fundamentacion`, `metas`, `objetivos`, `contenidos`, `capacidades`, `transversales`, `unidades`, `estrategias`, `formatos_pedagogicos`, `recursos`, `articulacion`, `evaluacion_criterios`, `evaluacion_instrumentos`, `evaluacion_momentos`, `bibliografia`, `estado`, `devolucion_directivo`, `revisado_por`, `fecha_revision`) VALUES
(4, 9, 34, 2026, 'A', 'Curso participativo, con interés por la salud y el deporte. Reconoce órganos, pero describe los sistemas de manera aislada.', 'Se propone comprender el organismo como un sistema integrado y relacionarlo con los hábitos de vida y el ambiente.', '["Explicar el funcionamiento del cuerpo humano de forma integral, considerando las interrelaciones entre los sistemas biológicos y el entorno.","Diseñar y participar de acciones de promoción de la salud en sus propias comunidades desde un enfoque integral, utilizando estrategias que involucren análisis de datos, argumentación y toma de decisiones.","Construir explicaciones y posicionamientos en torno a debates sociocientíficos actuales y a la evolución biológica, utilizando los conocimientos sobre genética y reconociendo el origen común de todos los seres vivos."]', '["Explicar el funcionamiento integrado del cuerpo humano.","Relacionar hábitos, ambiente y salud con evidencias."]', '[{"texto":"Interpretación del cuerpo humano, desde la integración de sistemas y subsistemas que conforman al organismo e interactúan para permitir la vida.","meta":"Explicar el funcionamiento del cuerpo humano de forma integral, considerando las interrelaciones entre los sistemas biológicos y el entorno.","indicadores":["Explica algunas respuestas del organismo frente a estímulos (externos o internos), a partir del concepto de homeostasis.","Reconoce y ubica, en las cavidades del cuerpo humano, los diferentes sistemas y sus órganos, evidenciando relaciones y conexiones.","Identifica cómo se distribuyen los nutrientes y gases respiratorios por el cuerpo, y cómo se eliminan las distintas sustancias de desecho, relacionando los órganos y tejidos de los sistemas estudiados.","Utiliza la noción de sistema, para analizar procesos de intercambios y transformaciones de materia y energía, a lo largo del proceso de nutrición.","Predice y explica respuestas frente a casos hipotéticos de estímulos (por ejemplo, consumir alimentos salados, correr, sentir miedo, quemarse, besar, agitación por actividad física, situaciones de riesgo, entre otros) y las relaciona, de manera coherente, con las funciones de los sistemas estudiados.","Ejemplifica, con situaciones cotidianas, la relación de los sistemas nervioso y endócrino con los demás sistemas (digestivo, por ejemplo, dolor de panza, cólicos, entre otros; reacciones involuntarias como la respiración, contracción muscular, el pulso, entre otros)."],"fuente":"pda_2025","contenido_id":1341,"prioridad":"esencial"},{"texto":"Reconocimiento de la relación entre hábitos de vida, conductas individuales y factores ambientales, y las respuestas del organismo humano.","meta":"Explicar el funcionamiento del cuerpo humano de forma integral, considerando las interrelaciones entre los sistemas biológicos y el entorno.","indicadores":["Reconoce los disruptores endocrinos en etiquetas e información de productos de uso cotidiano (alimentos, maquillaje, cosmética, entre otros) y los identifica como compuestos químicos que afectan la salud.","Identifica el efecto de consumir alimentos ultraprocesados, en relación con el impacto que generan sobre los sistemas estudiados.","Conoce y utiliza medidas de seguridad, frente a agentes químicos o físicos que causan alteraciones de los sistemas biológicos.","Problematiza el consumo de algunas sustancias (tabaco, alcohol, café, ansiolíticos, proteína, entre otras), reconociendo el impacto en el funcionamiento del cuerpo humano."],"fuente":"pda_2025","contenido_id":1342,"prioridad":"esencial"},{"texto":"Reconocimiento del sistema endócrino, como parte constitutiva de la modulación de ciertas conductas, emociones, respuestas fisiológicas y del desarrollo humano.","meta":"Explicar el funcionamiento del cuerpo humano de forma integral, considerando las interrelaciones entre los sistemas biológicos y el entorno.","indicadores":["Reconoce los principales órganos del sistema endócrino, y los relaciona con la producción, liberación y almacenamiento de hormonas específicas.","Establece relaciones lógicas (por ejemplo, utilizando flechas sobre representaciones gráficas), basadas en el funcionamiento del sistema endócrino, relacionando estímulos, glándulas, hormonas, órganos blanco y funciones o respuestas.","Analiza el proceso de retroalimentación hormonal (por ejemplo, de hormonas sexuales), a partir de la interpretación de representaciones gráficas.","Explica el ciclo menstrual, retomando conceptos como gónadas y hormonas sexuales, y relaciona las variaciones hormonales con los cambios fisiológicos que ocurren durante el ciclo."],"fuente":"pda_2025","contenido_id":1340,"prioridad":"esencial"},{"texto":"Caracterización de los factores determinantes de la salud, por ejemplo, biológicos, ambientales, estilo de vida, atención sanitaria, entre otros.","meta":"Diseñar y participar de acciones de promoción de la salud en sus propias comunidades desde un enfoque integral, utilizando estrategias que involucren análisis de datos, argumentación y toma de decisiones.","indicadores":["Reconoce casos o situaciones que ejemplifican la influencia de distintos tipos de determinantes en la salud individual y poblacional.","Identifica que poder ejercer plenamente la sexualidad se constituye como un factor determinante de salud y conversa sobre diferentes formas de habitarla, por ejemplo, reasignación de sexo, hormonización, fecundación, fertilización natural, fertilización asistida (Ley 26.862), donación de óvulos, aborto espontáneo e interrupción voluntaria del embarazo (Ley 27.610), Ley de Parto Respetado (Ley 25.929), entre otras.","Reconoce algunas enfermedades producidas por la contaminación biológica de alimentos (cólera, hepatitis, botulismo, entre otras), valorando la higiene y seguridad en los procesos de producción alimenticia.","Problematiza la idea de consumo, reconociendo que el consumo problemático puede deberse a una multiplicidad de factores, y que su abordaje requiere de una mirada integral sobre la salud."],"fuente":"pda_2025","contenido_id":1334,"prioridad":"esencial"},{"texto":"Comprensión del flujo de la información genética.","meta":"Construir explicaciones y posicionamientos en torno a debates sociocientíficos actuales y a la evolución biológica, utilizando los conocimientos sobre genética y reconociendo el origen común de todos los seres vivos.","indicadores":["Analiza el proceso histórico de construcción de conocimiento sobre el flujo de la información genética, reconociendo eventos y sucesos claves a lo largo del siglo XX.","Conceptualiza el gen como una unidad de información vinculada con la hebra de ADN.","Establece relaciones entre ADN, ARN y proteínas, teniendo en cuenta la forma en que fluye la información genética.","Modeliza las moléculas de ADN y ARN, reconociendo diferencias y similitudes."],"fuente":"pda_2025","contenido_id":1345,"prioridad":"complementario"}]', '["Pensamiento crítico","Oralidad, lectura y escritura","Ciudadanía local, global y digital"]', '[{"tema":"ESI","como":"Cuidado del propio cuerpo y respeto por la diversidad corporal."}]', '[{"titulo":"Un cuerpo integrado","periodo":"Marzo - junio","horas":65,"contenidos":"Integración de sistemas y sistema endócrino.","actividades":"Modelos, mediciones en reposo y en actividad."},{"titulo":"Salud y ambiente","periodo":"Julio - septiembre","horas":50,"contenidos":"Determinantes de la salud y hábitos.","actividades":"Encuesta y campaña de promoción de la salud."},{"titulo":"Información genética","periodo":"Octubre - diciembre","horas":50,"contenidos":"Flujo de la información genética.","actividades":"Modelización y debate."}]', 'Indagación, modelización, análisis de datos y debate.', '["Materia/Asignatura","Laboratorio","Proyecto"]', 'Microscopio, modelos anatómicos, tensiómetro, planillas.', 'Proyecto "El cuerpo humano y la actividad física" con Educación Física y Matemática.', 'Explica interrelaciones entre sistemas, usa evidencias, argumenta y trabaja en equipo.', 'Rúbrica de informe, portfolio y exposición.', 'Inicial: red conceptual. Formativa: devoluciones y coevaluación. Final: producto del proyecto.', 'Currículum Córdoba. Progresiones de Aprendizaje: Ciencias Naturales (versión en consulta 2025).', 'aprobada', 'Aprobada. Buen trabajo de articulación con otros espacios.', 2, '2026-03-30 11:15:00');
INSERT INTO `planificaciones_anuales` (`id`, `docente_id`, `espacio_id`, `anio_lectivo`, `division`, `diagnostico`, `fundamentacion`, `metas`, `objetivos`, `contenidos`, `capacidades`, `transversales`, `unidades`, `estrategias`, `formatos_pedagogicos`, `recursos`, `articulacion`, `evaluacion_criterios`, `evaluacion_instrumentos`, `evaluacion_momentos`, `bibliografia`, `estado`, `devolucion_directivo`, `revisado_por`, `fecha_revision`) VALUES
(5, 8, 39, 2027, 'A', 'Se completa al comenzar el ciclo lectivo 2027.', 'Se continúa el trabajo sobre proyecto de vida saludable.', '["Diseñar, gestionar y sostener un proyecto de vida saludable, personal y colectivo, con perspectiva a lo largo de toda la vida, mediante la toma de decisiones conscientes y autónomas sobre hábitos de bienestar integral.","Consolidar una identidad corporal crítica y autónoma, asumir un rol activo y responsable en la construcción de la cultura corporal, mediante la adaptación y transferencia de habilidades motrices complejas y del análisis/cuestionamiento de los discursos socioculturales dominantes sobre el cuerpo y el movimiento, en prácticas corporales diversas."]', '[]', '[{"texto":"Comprensión de la interrelación entre la actividad física y el funcionamiento integrado de los sistemas corporales, para el bienestar integral.","meta":"Diseñar, gestionar y sostener un proyecto de vida saludable, personal y colectivo, con perspectiva a lo largo de toda la vida, mediante la toma de decisiones conscientes y autónomas sobre hábitos de bienestar integral.","indicadores":["Identifica las principales funciones de los sistemas muscular, óseo, cardiovascular, respiratorio y nervioso, y sus interrelaciones en la práctica de actividad física.","Analiza y describe la interdependencia funcional entre al menos dos sistemas corporales (por ejemplo, cardiovascular y respiratorio) durante una práctica de actividad física, y explica cómo la adaptación de un sistema influye en el otro.","Propone actividades físicas específicas que contribuyen al bienestar integral y justifica su elección según objetivos y contexto (escolar, familiar, comunitario).","Evalúa el impacto de hábitos de vida sedentarios en el bienestar general e identifica cambios posibles para reducir el sedentarismo.","Reflexiona críticamente sobre la relación entre su condición motriz y factores externos (descanso, alimentación, entorno socioeconómico o emocional) y establece un vínculo entre práctica y cuidado integral y sostenible de su salud, a largo plazo."],"fuente":"pda_2025","contenido_id":1536,"prioridad":"esencial"},{"texto":"Selección y aplicación de herramientas y procedimientos necesarios para la construcción autónoma y responsable de un proyecto de vida saludable.","meta":"Diseñar, gestionar y sostener un proyecto de vida saludable, personal y colectivo, con perspectiva a lo largo de toda la vida, mediante la toma de decisiones conscientes y autónomas sobre hábitos de bienestar integral.","indicadores":["Identifica, selecciona y aplica herramientas de monitoreo (diario de práctica, escala de percepción de esfuerzo, registro de sueño), para valorar su condición motriz y tomar decisiones autónomas sobre su bienestar integral.","Diseña y aplica procedimientos de planificación (como la dosificación de la carga o la definición de metas a corto y largo plazo), coherentes con sus objetivos personales de bienestar integral.","Analiza los diferentes factores que influyen en la salud (biológicos, emocionales, sociales y ambientales) e identifica hábitos y obstáculos que afectan el cuidado personal y colectivo.","Registra resultados de su plan de bienestar (actividad física, descanso, alimentación) y ajusta la intensidad, la frecuencia o los tiempos según esos datos."],"fuente":"pda_2025","contenido_id":1535,"prioridad":"esencial"},{"texto":"Aplicación de capacidades condicionales, para resolver desafíos motrices en entornos variados y dinámicos.","meta":"Consolidar una identidad corporal crítica y autónoma, asumir un rol activo y responsable en la construcción de la cultura corporal, mediante la adaptación y transferencia de habilidades motrices complejas y del análisis/cuestionamiento de los discursos socioculturales dominantes sobre el cuerpo y el movimiento, en prácticas corporales diversas.","indicadores":["Selecciona y aplica, de manera oportuna, la capacidad condicional predominante (velocidad, fuerza explosiva o resistencia) que requiere el desafío motriz.","Combina diferentes capacidades condicionales (por ejemplo, aplica fuerza inmediatamente después de un desplazamiento rápido), para ejecutar secuencias de movimiento complejas con objetivos múltiples.","Explica los beneficios de la resistencia aeróbica, para la salud cardiovascular, y la importancia de la resistencia anaeróbica, en la resolución de desafíos motrices de alta intensidad.","Identifica posturas y técnicas adecuadas en ejercicios de fuerza, y justifica verbalmente por qué constituyen un principio de seguridad y cuidado de su propia corporeidad."],"fuente":"pda_2025","contenido_id":1532,"prioridad":"esencial"}]', '["Trabajo colaborativo y cooperativo"]', '[]', '[]', NULL, '["Taller"]', NULL, NULL, NULL, NULL, NULL, NULL, 'borrador', NULL, NULL, NULL);
INSERT INTO `planificacion_comentarios` (`planificacion_id`, `usuario_id`, `comentario`, `estado_asociado`) VALUES
