INSERT INTO `planificacion_comentarios` (`planificacion_id`, `usuario_id`, `comentario`, `estado_asociado`) VALUES
(3, 2, 'Ampliar los criterios de evaluación y sumar instancias de autoevaluación. Detallar las normas de seguridad del laboratorio.', 'requiere_ajustes');
INSERT INTO `secuencias_didacticas` (`id`, `docente_id`, `espacio_id`, `titulo`, `planificacion_id`, `fundamentacion`, `objetivos`, `contenidos`, `capacidades`, `formato`, `tiempo_estimado`, `agrupamientos`, `ambiente`, `clases`, `producto`, `evaluacion_criterios`, `evaluacion_instrumentos`, `recursos`, `bibliografia`, `tipo_articulacion`, `articulacion_eje`, `articulacion_materias`, `estado`, `devolucion_directivo`) VALUES
(1, 4, 41, 'Compost: del residuo al abono', 1, 'El compostaje permite observar un proceso biológico con datos propios y discutir alternativas al fertilizante sintético.', 'Comprender el compostaje como proceso dentro del agroecosistema.\nRegistrar e interpretar temperatura, humedad y volumen.\nFundamentar el uso de compost en la huerta escolar.', '[{"texto":"Aproximación a los conceptos de sistemas, agroecosistemas, agroambientes y sustentabilidad.","meta":null,"indicadores":[],"fuente":"diseno_2011_2015","contenido_id":1592,"prioridad":"esencial"},{"texto":"Comprensión de fundamentos, alcances y limitaciones de prácticas de producción alternativa, orgánicas o ecológicas.","meta":null,"indicadores":[],"fuente":"diseno_2011_2015","contenido_id":1595,"prioridad":"esencial"},{"texto":"Implementación y análisis de modelos que incluyan buenas prácticas en sistemas de producción vegetal de importancia regional.","meta":null,"indicadores":[],"fuente":"diseno_2011_2015","contenido_id":1599,"prioridad":"esencial"}]', '["Abordaje y resolución de situaciones problemáticas","Trabajo colaborativo y cooperativo"]', 'Taller', '5 clases (12 horas cátedra)', 'Equipos de 4 o 5 con roles rotativos: registro, medición, herramientas y seguridad.', 'Huerta escolar y aula.', '[{"titulo":"¿A dónde van los residuos?","momento":"inicio","duracion":"2 HC","actividades":"Relevamiento de residuos orgánicos de la escuela, ideas previas y pregunta de trabajo.","recursos":"Planilla y balanza","evaluativa":false},{"titulo":"Armamos la compostera","momento":"desarrollo","duracion":"3 HC","actividades":"Construcción por capas, medición inicial de temperatura y volumen. Normas de seguridad.","recursos":"Herramientas, guantes y termómetro","evaluativa":false},{"titulo":"Medimos y registramos","momento":"desarrollo","duracion":"3 HC","actividades":"Mediciones en semanas sucesivas, tabla de datos y primer gráfico.","recursos":"Termómetro y planilla","evaluativa":true},{"titulo":"Interpretamos los datos","momento":"desarrollo","duracion":"2 HC","actividades":"Comparación entre equipos y explicación de las diferencias.","recursos":"Gráficos","evaluativa":false},{"titulo":"Compartimos","momento":"cierre","duracion":"2 HC","actividades":"Presentación del informe y propuesta de uso en los canteros. Autoevaluación.","recursos":"Rúbrica","evaluativa":true}]', 'Informe con datos propios y recomendación de uso.', 'Registra con regularidad, interpreta los datos, fundamenta la recomendación y respeta las normas de seguridad.', 'Planilla de registro, rúbrica de informe y autoevaluación.', 'Huerta, compostera, termómetro, balanza y planillas.', 'Diseño Curricular, Tomo 11: Agro y Ambiente (2012-2015).', 'declarativa', 'Lectura e interpretación de datos', 'Matemática 4.º', 'aprobada', 'Secuencia clara y bien graduada.');
INSERT INTO `secuencias_didacticas` (`id`, `docente_id`, `espacio_id`, `titulo`, `planificacion_id`, `fundamentacion`, `objetivos`, `contenidos`, `capacidades`, `formato`, `tiempo_estimado`, `agrupamientos`, `ambiente`, `clases`, `producto`, `evaluacion_criterios`, `evaluacion_instrumentos`, `recursos`, `bibliografia`, `tipo_articulacion`, `articulacion_eje`, `articulacion_materias`, `estado`, `devolucion_directivo`) VALUES
(2, 7, 33, 'El pulso de una recta: función lineal con datos propios', 2, 'Los datos de frecuencia cardíaca tomados en Educación Física permiten discutir cuándo un modelo lineal es adecuado y cuáles son sus límites.', 'Reconocer variación lineal en datos.\nInterpretar pendiente y ordenada en contexto.\nDiscutir los límites del modelo.', '[{"texto":"Análisis de funciones lineales f(x) = kx + b, presentadas en textos, tablas, gráficos y fórmulas, en situaciones extra e intramatemáticas.","meta":"Modelizar situaciones vinculadas a la función lineal, cuadrática, racional, exponencial, logarítmica y trigonométricas.","indicadores":["Reconoce y explica funciones lineales en base a la interpretación de textos, tablas, gráficos y fórmulas.","Interpreta y comunica dominio e imagen en situaciones que se modelizan con funciones lineales.","Reconoce gráficamente y comunica puntos de intersección con los ejes coordenados, intervalos de positividad y negatividad, apelando al uso del software cuando sea posible.","Relaciona la variación de x en función de y en la ecuación y = kx + b al escribir la inversa de una función lineal dada.","Interpreta y explica las características del gráfico de la inversa de una función lineal dada.","Lee una situación, selecciona la información relevante y usa la función lineal para modelizarla.","Busca y selecciona información en distintas fuentes sobre situaciones reales (incluidas las de interés simple) que se modelizan con funciones lineales."],"fuente":"pda_2025","contenido_id":1309,"prioridad":"esencial"}]', '["Abordaje y resolución de situaciones problemáticas","Oralidad, lectura y escritura"]', 'Laboratorio', '4 clases (8 horas cátedra)', 'Parejas y puesta en común.', 'Aula y patio.', '[{"titulo":"Leemos datos","momento":"inicio","duracion":"2 HC","actividades":"Análisis de la tabla de intensidad y frecuencia cardíaca. Formulación de hipótesis.","recursos":"Tabla de datos","evaluativa":false},{"titulo":"De la tabla a la recta","momento":"desarrollo","duracion":"2 HC","actividades":"Gráfico, recta que mejor aproxima, pendiente y ordenada.","recursos":"GeoGebra","evaluativa":false},{"titulo":"¿Siempre es lineal?","momento":"desarrollo","duracion":"2 HC","actividades":"Dominio con sentido y límites del modelo. Comparación entre equipos.","recursos":"Planilla de cálculo","evaluativa":true},{"titulo":"Comunicamos","momento":"cierre","duracion":"2 HC","actividades":"Informe de modelización y coevaluación.","recursos":"Lista de cotejo","evaluativa":true}]', 'Informe de modelización.', 'Construye el modelo, interpreta los parámetros, señala límites y comunica.', 'Informe, lista de cotejo y coevaluación.', 'Datos del curso, GeoGebra y planilla de cálculo.', 'Progresiones de Aprendizaje: Matemática (versión en consulta 2025).', 'colaborativa', 'El cuerpo humano y la actividad física', 'Educación Física 4.º, Biología 4.º', 'pendiente_revision', NULL);
INSERT INTO `proyectos_articulados` (`id`, `creador_id`, `titulo`, `modalidad`, `anio_lectivo`, `curso`, `division`, `vigencia`, `fecha_inicio`, `fecha_fin`, `eje`, `fundamentacion`, `marco_integrador`, `objetivos`, `capacidades`, `transversales`, `producto_final`, `horas_compartidas`, `organizacion`, `evaluacion_criterios`, `evaluacion_instrumentos`, `evaluacion_momentos`, `estado`, `devolucion`, `revisado_por`, `fecha_presentacion`, `fecha_revision`) VALUES
(1, 8, 'El cuerpo humano y la actividad física', 'proyecto_interdisciplinario', 2026, 4, 'A', 'etapa', '2026-08-03', '2026-11-27', '¿Qué le pasa a nuestro cuerpo cuando nos movemos y cómo podemos medirlo y explicarlo?', 'Un mismo fenómeno se mide en Educación Física, se modeliza en Matemática y se explica en Biología. Cada espacio aporta sus propios aprendizajes.', 'Cuerpo como sistema integrado, variación y modelo, hábitos saludables.', 'Registrar datos propios en actividad física.\nModelizar la relación entre intensidad y frecuencia cardíaca.\nExplicar las respuestas del organismo con evidencias.', '["Abordaje y resolución de situaciones problemáticas","Pensamiento crítico","Trabajo colaborativo y cooperativo"]', '["ESI"]', 'Informe y muestra "Nuestro cuerpo en movimiento", abierta a la comunidad.', 0, 'Cada docente trabaja en sus horas, con tres encuentros conjuntos en el playón y el aula. Equipos de 4 estudiantes.', 'Calidad del registro, pertinencia del modelo, explicación con evidencias y trabajo en equipo.', 'Rúbrica común, portfolio y exposición.', 'Al inicio, en cada encuentro y en la muestra final.', 'en_ejecucion', 'Proyecto autorizado. Compartir el informe final con el curso de 5.º.', 2, '2026-07-20 10:00:00', '2026-07-27 12:00:00');
INSERT INTO `proyectos_articulados` (`id`, `creador_id`, `titulo`, `modalidad`, `anio_lectivo`, `curso`, `division`, `vigencia`, `fecha_inicio`, `fecha_fin`, `eje`, `fundamentacion`, `marco_integrador`, `objetivos`, `capacidades`, `transversales`, `producto_final`, `horas_compartidas`, `organizacion`, `evaluacion_criterios`, `evaluacion_instrumentos`, `evaluacion_momentos`, `estado`, `devolucion`, `revisado_por`, `fecha_presentacion`, `fecha_revision`) VALUES
(2, 9, 'Suelo vivo, salud y ambiente', 'tiempo_compartido', 2027, 4, 'A', 'anual', NULL, NULL, '¿Cómo influye la manera de producir en el ambiente y en nuestra salud?', 'Propuesta para 2027 entre Biología y Sistemas Agroambientales, combinación que los documentos de Córdoba mencionan como ejemplo para 4.º año.', 'Agroecosistema, ambiente y salud.', NULL, '["Pensamiento crítico"]', '["Educación Ambiental Integral"]', 'Guía de buenas prácticas para la huerta escolar.', 2, 'Dos horas semanales compartidas.', NULL, NULL, NULL, 'en_acuerdo', NULL, NULL, NULL, NULL);
INSERT INTO `proyecto_articulado_participantes` (`proyecto_id`, `docente_id`, `espacio_id`, `invitacion`, `tema`, `contenidos`, `actividades`, `recursos`, `saberes_propios`, `evaluacion_aporte`, `horas_cede`, `disponibilidad`, `conformidad`, `fecha_conformidad`) VALUES
(1, 8, 39, 'aceptado', 'Cuerpo humano en movimiento', '[{"texto":"Comprensión de la interrelación entre la actividad física y el funcionamiento integrado de los sistemas corporales, para el bienestar integral.","meta":"Diseñar, gestionar y sostener un proyecto de vida saludable, personal y colectivo, con perspectiva a lo largo de toda la vida, mediante la toma de decisiones conscientes y autónomas sobre hábitos de bienestar integral.","indicadores":["Identifica las principales funciones de los sistemas muscular, óseo, cardiovascular, respiratorio y nervioso, y sus interrelaciones en la práctica de actividad física.","Analiza y describe la interdependencia funcional entre al menos dos sistemas corporales (por ejemplo, cardiovascular y respiratorio) durante una práctica de actividad física, y explica cómo la adaptación de un sistema influye en el otro.","Propone actividades físicas específicas que contribuyen al bienestar integral y justifica su elección según objetivos y contexto (escolar, familiar, comunitario).","Evalúa el impacto de hábitos de vida sedentarios en el bienestar general e identifica cambios posibles para reducir el sedentarismo.","Reflexiona críticamente sobre la relación entre su condición motriz y factores externos (descanso, alimentación, entorno socioeconómico o emocional) y establece un vínculo entre práctica y cuidado integral y sostenible de su salud, a largo plazo."],"fuente":"pda_2025","contenido_id":1536,"prioridad":"esencial"},{"texto":"Selección y aplicación de herramientas y procedimientos necesarios para la construcción autónoma y responsable de un proyecto de vida saludable.","meta":"Diseñar, gestionar y sostener un proyecto de vida saludable, personal y colectivo, con perspectiva a lo largo de toda la vida, mediante la toma de decisiones conscientes y autónomas sobre hábitos de bienestar integral.","indicadores":["Identifica, selecciona y aplica herramientas de monitoreo (diario de práctica, escala de percepción de esfuerzo, registro de sueño), para valorar su condición motriz y tomar decisiones autónomas sobre su bienestar integral.","Diseña y aplica procedimientos de planificación (como la dosificación de la carga o la definición de metas a corto y largo plazo), coherentes con sus objetivos personales de bienestar integral.","Analiza los diferentes factores que influyen en la salud (biológicos, emocionales, sociales y ambientales) e identifica hábitos y obstáculos que afectan el cuidado personal y colectivo.","Registra resultados de su plan de bienestar (actividad física, descanso, alimentación) y ajusta la intensidad, la frecuencia o los tiempos según esos datos."],"fuente":"pda_2025","contenido_id":1535,"prioridad":"esencial"}]', 'Circuitos de distinta intensidad y toma de pulso en reposo, durante y después de la actividad.', 'Cronómetros, conos y planillas.', 'Capacidades condicionales y prácticas deportivas del año.', 'Lista de cotejo del registro y del cuidado propio y ajeno.', 0, 'Martes, primer bloque', 1, '2026-07-18 09:00:00');
INSERT INTO `proyecto_articulado_participantes` (`proyecto_id`, `docente_id`, `espacio_id`, `invitacion`, `tema`, `contenidos`, `actividades`, `recursos`, `saberes_propios`, `evaluacion_aporte`, `horas_cede`, `disponibilidad`, `conformidad`, `fecha_conformidad`) VALUES
(1, 7, 33, 'aceptado', 'Funciones lineales', '[{"texto":"Análisis de funciones lineales f(x) = kx + b, presentadas en textos, tablas, gráficos y fórmulas, en situaciones extra e intramatemáticas.","meta":"Modelizar situaciones vinculadas a la función lineal, cuadrática, racional, exponencial, logarítmica y trigonométricas.","indicadores":["Reconoce y explica funciones lineales en base a la interpretación de textos, tablas, gráficos y fórmulas.","Interpreta y comunica dominio e imagen en situaciones que se modelizan con funciones lineales.","Reconoce gráficamente y comunica puntos de intersección con los ejes coordenados, intervalos de positividad y negatividad, apelando al uso del software cuando sea posible.","Relaciona la variación de x en función de y en la ecuación y = kx + b al escribir la inversa de una función lineal dada.","Interpreta y explica las características del gráfico de la inversa de una función lineal dada.","Lee una situación, selecciona la información relevante y usa la función lineal para modelizarla.","Busca y selecciona información en distintas fuentes sobre situaciones reales (incluidas las de interés simple) que se modelizan con funciones lineales."],"fuente":"pda_2025","contenido_id":1309,"prioridad":"esencial"}]', 'Tabla y gráfico con los datos del curso, recta que aproxima, interpretación de la pendiente y límites del modelo.', 'GeoGebra y planilla de cálculo.', 'Función cuadrática y estadística.', 'Informe de modelización.', 0, 'Jueves, segundo bloque', 1, '2026-07-18 09:00:00');
INSERT INTO `proyecto_articulado_participantes` (`proyecto_id`, `docente_id`, `espacio_id`, `invitacion`, `tema`, `contenidos`, `actividades`, `recursos`, `saberes_propios`, `evaluacion_aporte`, `horas_cede`, `disponibilidad`, `conformidad`, `fecha_conformidad`) VALUES
(1, 9, 34, 'aceptado', 'Sistemas del cuerpo integrados', '[{"texto":"Interpretación del cuerpo humano, desde la integración de sistemas y subsistemas que conforman al organismo e interactúan para permitir la vida.","meta":"Explicar el funcionamiento del cuerpo humano de forma integral, considerando las interrelaciones entre los sistemas biológicos y el entorno.","indicadores":["Explica algunas respuestas del organismo frente a estímulos (externos o internos), a partir del concepto de homeostasis.","Reconoce y ubica, en las cavidades del cuerpo humano, los diferentes sistemas y sus órganos, evidenciando relaciones y conexiones.","Identifica cómo se distribuyen los nutrientes y gases respiratorios por el cuerpo, y cómo se eliminan las distintas sustancias de desecho, relacionando los órganos y tejidos de los sistemas estudiados.","Utiliza la noción de sistema, para analizar procesos de intercambios y transformaciones de materia y energía, a lo largo del proceso de nutrición.","Predice y explica respuestas frente a casos hipotéticos de estímulos (por ejemplo, consumir alimentos salados, correr, sentir miedo, quemarse, besar, agitación por actividad física, situaciones de riesgo, entre otros) y las relaciona, de manera coherente, con las funciones de los sistemas estudiados.","Ejemplifica, con situaciones cotidianas, la relación de los sistemas nervioso y endócrino con los demás sistemas (digestivo, por ejemplo, dolor de panza, cólicos, entre otros; reacciones involuntarias como la respiración, contracción muscular, el pulso, entre otros)."],"fuente":"pda_2025","contenido_id":1341,"prioridad":"esencial"},{"texto":"Reconocimiento de la relación entre hábitos de vida, conductas individuales y factores ambientales, y las respuestas del organismo humano.","meta":"Explicar el funcionamiento del cuerpo humano de forma integral, considerando las interrelaciones entre los sistemas biológicos y el entorno.","indicadores":["Reconoce los disruptores endocrinos en etiquetas e información de productos de uso cotidiano (alimentos, maquillaje, cosmética, entre otros) y los identifica como compuestos químicos que afectan la salud.","Identifica el efecto de consumir alimentos ultraprocesados, en relación con el impacto que generan sobre los sistemas estudiados.","Conoce y utiliza medidas de seguridad, frente a agentes químicos o físicos que causan alteraciones de los sistemas biológicos.","Problematiza el consumo de algunas sustancias (tabaco, alcohol, café, ansiolíticos, proteína, entre otras), reconociendo el impacto en el funcionamiento del cuerpo humano."],"fuente":"pda_2025","contenido_id":1342,"prioridad":"esencial"}]', 'Explicación de los cambios circulatorios y respiratorios, y análisis de hábitos.', 'Modelos anatómicos y tensiómetro.', 'Información genética.', 'Rúbrica de explicación con evidencias.', 0, 'Miércoles, segundo bloque', 1, '2026-07-18 09:00:00');
INSERT INTO `proyecto_articulado_participantes` (`proyecto_id`, `docente_id`, `espacio_id`, `invitacion`, `tema`, `contenidos`, `actividades`, `recursos`, `saberes_propios`, `evaluacion_aporte`, `horas_cede`, `disponibilidad`, `conformidad`, `fecha_conformidad`) VALUES
(2, 9, 34, 'aceptado', 'Ambiente y salud', '[{"texto":"Reconocimiento del ambiente como una dimensión fundamental en la promoción de la salud integral.","meta":"Diseñar y participar de acciones de promoción de la salud en sus propias comunidades desde un enfoque integral, utilizando estrategias que involucren análisis de datos, argumentación y toma de decisiones.","indicadores":["Releva, de manera sistemática, el ambiente cercano, registrando problemáticas/casos de deterioro ambiental.","Elabora relaciones causa-consecuencia entre diferentes casos de salud ambiental y de las personas.","Analiza casos locales que ponen de manifiesto la relación entre salud ambiental y de las personas, desde el enfoque “Una salud” (por ejemplo “Madres de Ituzaingó”, inundaciones en Sierras Chicas, fumigaciones ilegales, basurales a cielo abierto, entre otros).","Construye argumentos (a favor o en contra) sobre los diferentes modelos productivos y de consumo, contemplando su huella de producción o impacto en un contexto de crisis ambiental."],"fuente":"pda_2025","contenido_id":1338,"prioridad":"esencial"}]', NULL, NULL, NULL, NULL, 2, NULL, 0, NULL);
